// ---------- estado
function empModal(h){reModal=null;showModal(h)}
function ensureEmp(){if(!S.emp)S.emp={farms:{},ind:{},air:{},gen:{bulls:[],cotas:[],central:0,offers:[],od:-1},lux:{house:0,cars:{},fav:null,haras:0,champs:[]},vila:{biz:{},don:{},pop:1200},pol:{festa:0,festaD:-1,time:null,pref:0,prefEnd:0,elec:0,camp:0},seg:0,cont:0,dre:[],ev:[],vis:{},mag:EMAG.map(m=>m[2]),best:99,hpos:null};
 const E=S.emp;E.gen.cotas=E.gen.cotas||[];E.mag=E.mag||EMAG.map(m=>m[2]);if(E.pol.time)ensureTeam(E.pol.time);return E}
const empOn=()=>myNW()>=1e6||(S.emp&&Object.keys(S.emp.farms).length>0);
const fown=id=>S.emp&&S.emp.farms[id];
const nFarmsT=t=>EFARMS.filter(f=>fown(f.id)&&(t==='all'||t.includes(f.tp))).length;
// vila: 0 = não tem, 1 = em obra, 2 = pronto (valores antigos "1" contam como pronto)
function vSt(k,id){const v=S.emp&&S.emp.vila[k][id];if(!v)return 0;return typeof v==='object'&&S.day<v.d?1:2}
const vReady=(k,id)=>vSt(k,id)===2;
function empAssetVal(){const E=ensureEmp();let v=0;EFARMS.forEach(f=>{if(fown(f.id))v+=fown(f.id).val});EIND.forEach(i=>{const o=E.ind[i.id];if(o)v+=i.p*(1+.5*o.lvl)*.85});
 for(const k in E.air)if(E.air[k])v+=EAIR[k].p*.75;v+=EHOUSE.slice(1,E.lux.house+1).reduce((s,h)=>s+h.p*.7,0);ECARS.forEach(c=>{if(E.lux.cars[c.id])v+=c.p*.8});if(E.lux.haras)v+=1.5e6*.7;E.lux.champs.forEach(c=>v+=c.p*.8);
 E.gen.bulls.forEach(b=>{if(S.herd.some(x=>x.id===b.id))v+=b.p*.6});E.gen.cotas.forEach(c=>v+=c.p*.7);if(E.gen.central)v+=3e6*.7;EBIZ.forEach(b=>{if(E.vila.biz[b.id])v+=b.p*.9});if(E.pol.time)v+=E.pol.time.val||0;return v}
const _nwEmp=netWorth;netWorth=function(){let v=_nwEmp();if(S&&S.emp)v+=empAssetVal();return v};
