function mkPlayer(pos,ov){return{n:pick(EPN)+' '+pick(EPS),pos,ov:Math.round(clamp(ov,30,99)),g:0}}
function teamOpp(T){const off=(T.div*4+(T.seas||0)*3)%ETEAMS.length;return Array.from({length:11},(_,i)=>ETEAMS[(off+i)%ETEAMS.length])}
function oppF(T,n){return EDIV[T.div].f0+(hsh(n+T.div)%17)-8}
function teamF(T){return T.squad.reduce((s,p)=>s+p.ov,0)/T.squad.length}
function ensureTeam(T){if(!T.squad){T.squad=EPOS.map(p=>mkPlayer(p,(T.f||42)+rnd(-6,6)))}T.f=teamF(T);if(!T.tbl||!T.opp){T.opp=teamOpp(T);T.tbl={};T.opp.concat([ME_T]).forEach(n=>T.tbl[n]={p:0,gp:0,gc:0,j:0,v:0});T.j=0}T.hist=T.hist||[];T.games=T.games||[];return T}
function poisson(l){let k=0,p=1,L=Math.exp(-l);do{k++;p*=Math.random()}while(p>L&&k<12);return k-1}
function simGame(fa,fb,home){const pa=fa/(fa+fb),la=Math.max(.2,2.6*pa+(home?.25:0)),lb=Math.max(.2,2.6*(1-pa));return[poisson(la),poisson(lb)]}
function tblAdd(r,gf,ga){r.j++;r.gp+=gf;r.gc+=ga;if(gf>ga){r.p+=3;r.v++}else if(gf===ga)r.p+=1}
function tblSorted(T){return Object.keys(T.tbl).map(n=>Object.assign({n},T.tbl[n])).sort((a,b)=>b.p-a.p||(b.gp-b.gc)-(a.gp-a.gc)||b.gp-a.gp)}
function teamWeek(){const T=ensureTeam(S.emp.pol.time),opp=T.opp[T.j],home=T.j%2===0,[gf,ga]=simGame(T.f,oppF(T,opp),home);
 const W={1:4,ATA:4,MEI:2.2,VOL:1,LAT:.8,ZAG:.6,GOL:0},att=T.squad.filter(p=>W[p.pos]),gols=[];for(let i=0;i<gf;i++){let r=Math.random()*att.reduce((s,p)=>s+W[p.pos]*p.ov,0),pl=att[0];for(const p of att){r-=W[p.pos]*p.ov;if(r<=0){pl=p;break}}pl.g++;gols.push({m:ri(2,90),n:pl.n,me:1})}
 for(let i=0;i<ga;i++)gols.push({m:ri(2,90),n:opp,me:0});gols.sort((a,b)=>a.m-b.m);
 const pub=home?Math.round((1500+S.rep*60)*(1+T.div*1.7)*(gf>ga?1.1:1)*rnd(.85,1.15)):0,renda=pub*EDIV[T.div].tk;
 tblAdd(T.tbl[ME_T],gf,ga);tblAdd(T.tbl[opp],ga,gf);
 const rest=T.opp.filter(n=>n!==opp).sort(()=>Math.random()-.5);for(let i=0;i+1<rest.length;i+=2){const a=rest[i],b=rest[i+1],[x,y]=simGame(oppF(T,a),oppF(T,b),1);tblAdd(T.tbl[a],x,y);tblAdd(T.tbl[b],y,x)}
 if(renda)cash(renda,'Bilheteria do '+ME_T);
 const res=gf>ga?'✅':gf===ga?'➖':'❌';T.last=res+' '+(home?ME_T+' '+gf+' × '+ga+' '+opp:opp+' '+ga+' × '+gf+' '+ME_T);T.lastG={gols,pub,renda,home,opp,gf,ga,rd:T.j+1,div:T.div};T.j++;
 toast('⚽ '+T.last+(gols.filter(g=>g.me).length?' · gols: '+gols.filter(g=>g.me).map(g=>g.n.split(' ')[0]+' '+g.m+"'").join(', '):''),gf>=ga?'good':'bad');
 if(T.j>=11)seasonEnd(T)}
function seasonEnd(T){const L=tblSorted(T),pos=L.findIndex(x=>x.n===ME_T)+1,art=T.squad.slice().sort((a,b)=>b.g-a.g)[0];let msg='🏆 Fim da '+EDIV[T.div].n+': '+pos+'º lugar ('+T.tbl[ME_T].p+' pts).';
 if(pos===1){msg+=' 🥇 CAMPEÃO!';cash(EDIV[T.div].rev*4,'Premiação do título');S.rep=Math.min(100,S.rep+8)}
 if(pos<=4&&T.div<3){T.div++;msg+=' ⬆️ ACESSO para a '+EDIV[T.div].n+'!';S.rep=Math.min(100,S.rep+6);cash(EDIV[T.div].rev*2,'Premiação do acesso')}
 else if(pos>=11&&T.div>0){T.div--;msg+=' ⬇️ Rebaixado para a '+EDIV[T.div].n+'.';S.rep=Math.max(0,S.rep-3)}
 if(art&&art.g)msg+=' Artilheiro: '+art.n+' ('+art.g+' gols).';
 T.hist.unshift(msg);if(T.hist.length>6)T.hist.length=6;T.seas=(T.seas||0)+1;T.squad.forEach(p=>p.g=0);T.tbl=null;T.opp=null;ensureTeam(T);T.val=5e6*(1+T.div*1.6)*(T.f/50);
 empModal('<h3>⚽ Fim de temporada</h3><div class="card">'+msg+'</div><div class="btns"><button class="b gold" data-act="close">Bora pra próxima!</button></div>')}
