const _cashEmp=cash;cash=function(v,l){if(S&&S.emp&&l){const E=S.emp;
 if(v<0){if(E.pol.pref&&S.day<E.pol.prefEnd&&/ITR|Licença/i.test(l))v*=.5;if(vReady('biz','loja')&&/Ração|Semente/i.test(l))v*=.95;if(vReady('don','saude')&&/Hospital/i.test(l))v*=.5}
 else if(v>0){if(E.ind.laticinio&&/^Laticínio:/.test(l))v*=1.1;if(E.ind.armazem&&/^(Venda na caixa|Cooperativa)/.test(l))v*=1.05}}return _cashEmp(v,l)};
const _voEmp=valueOf;valueOf=function(a,m){let v=_voEmp(a,m);if(S&&S.emp&&(m==='frig'||m==='mkt')){const E=S.emp;if(E.ind.frigo&&m==='frig')v*=1.08;if(vReady('don','ponte'))v*=1.03;if(vReady('don','asfalto'))v*=1.05}return v};
const _cyEmp=cropYield;cropYield=function(c){let y=_cyEmp(c);if(S.emp&&S.emp.air.plane&&Math.random()<.1)y++;return y};
